from grow_helpers import *

def comparison():
    d=base('grow_life_cycle_comparison','The life-cycle comparison bureau','Use shared features without making a false rule','Compare named animal life cycles using similarities, differences and a valid counterexample.',1,['Describe a named animal life cycle.','Know that adults can reproduce and offspring grow.'],['Compare two species using the same feature.','Use a life-cycle stage as evidence for a difference.','Explain why one shared feature does not make two animals the same group.'],[('compare','Describe similarities and differences using the same feature.'),('larva','An immature stage with a different body form from the adult.'),('pupa','A developmental stage between larva and adult in insects with complete metamorphosis.'),('mammal','An animal in the group whose females produce milk for young.'),('counterexample','A case that shows an all-or-never claim is false.')],['Shared species cards, selected route, pencils; optional desk sorting labels.'],['Read the named-species cards; no observations of live animals are required.','Explain that the diagrams omit exact times and are not to scale.'],['Use the paper archive; do not collect eggs, disturb nests or handle wildlife.'],'All evidence needed is on paper or screen; sort or annotate cards at a desk.',[('All animals that lay eggs are birds.','Many other animals lay eggs; a platypus is an egg-laying mammal.','Ask which card provides a counterexample.'),('A pupa is just another word for any baby animal.','A pupa is a particular stage in insects such as monarch butterflies.','Ask whether a frog has a pupa.'),('An adult turns back into its own egg.','Adults produce a new generation; an individual does not become an egg again.','Ask whose life starts at the next egg.')],['Compare two named species with a feature word bank.','Complete a feature table and justify one similarity and two differences.','Test broad classification claims and state the limits of the sample.'],[FROG,MONARCH,PLATYPUS,ROBIN])
    v1=loop('Common frog: major changes in body form',['Eggs in pond','Tadpole\nlarva','Froglet\ngrowing legs','Adult frog\ncan reproduce'],'Adults produce the next generation of eggs.')
    v2=loop('Monarch: a different developmental route',['Egg on milkweed','Caterpillar\nlarva','Chrysalis\npupa','Adult monarch\ncan reproduce'],'A pupa is present here; it is not a stage in every insect.')
    v3=vis('Eggs do not mean the same animal group','Parallel comparisons of platypus and robin: both lay eggs, but platypus young receive milk and robin chicks receive food from parents. No arrow connects the animal groups.',[txt(40,25,920,60,'Compare one feature at a time',32,bold=True),rect(70,125,400,300),rect(530,125,400,300),txt(90,145,360,55,'Platypus: mammal',30,bold=True),txt(550,145,360,55,'Robin: bird',30,bold=True),ell(220,225,80,55,'#F4EAD6',ORANGE),ell(680,225,80,55,'#F4EAD6',ORANGE),txt(90,310,360,90,'Eggs in a burrow\nYoung receive milk',28),txt(550,310,360,90,'Eggs in a nest\nChicks receive food',28),txt(65,470,870,55,'Same egg-laying feature; different animal groups.',27)])
    cardspec=[('F • Common frog','Eggs are laid in pond water. Tadpoles are larvae with tails; they develop into froglets and then adults. No pupa stage.'),('M • Monarch butterfly','Eggs are laid on milkweed. Caterpillars are larvae; they become pupae, then adult butterflies. No milk feeding.'),('P • Platypus','A mammal that lays eggs in a burrow. The young hatch and receive milk from their mother; they grow to reproductive maturity. No pupa.'),('R • Robin','A bird that lays eggs in a nest. Chicks hatch, grow feathers and become fledglings, then reproductive adults. Parents bring food; no milk feeding.'),('Comparison rule','Use the same feature on both sides: egg location, pupa stage, or milk feeding. A blank in our evidence means not supplied, not automatically absent.'),('Cycle rule','Adults produce offspring. The next eggs belong to a new generation; the same individual does not turn back into an egg.')]
    d['slides']=[slide('Opening',2,'Four cases, one comparison challenge',['All four animals lay eggs.','Does that make all four birds?','Your job is to test the claim with evidence.'],'Invite a tentative response. No need to know the platypus in advance: the shared card supplies the needed evidence.'),slide('Retrieval',3,'Use the stage words carefully',['R1. What does an adult animal become able to do?','R2. Name an animal with a larva stage.','R3. Does one individual turn back into an egg?'],'R1 reproduce; R2 monarch, common frog or another accurate example; R3 no, the next generation starts with new offspring.'),slide('I do',8,'I choose a feature, then compare',['I follow the common-frog stages.','A tadpole and adult differ in body form.','I look for a pupa; none is present.'],'Think aloud: I compare the presence of a pupa, not whether the animal is attractive or large. The frog route includes a larva and major change, but no pupa. Time spans and detailed anatomy are omitted.',visual=v1),slide('I do',0,'I use the same feature for the monarch',['Both routes include eggs and a larva.','Only this monarch route has a pupa.','A shared stage does not make the whole cycle identical.'],'Shared I do time. Think aloud: I use a matching question: Is a pupa present? For the monarch, yes; for common frog, no. This is a justified difference. Do not generalise the monarch route to every insect.',visual=v2),slide('I do',0,'I test an “all” claim',['Platypus and robin both lay eggs.','Platypus young receive milk; robin chicks do not.','The platypus disproves “all egg-layers are birds”.'],'Shared I do time. Explain a counterexample as one real case that breaks the rule. Mammal classification does not depend solely on live birth. Compare named species; do not infer every detail about all mammals from one.',visual=v3),slide('We do',8,'Comparison bureau: shared-feature sort',['Use cards F, M, P and R.','W1. Group them by one feature, then regroup.','Explain why the groups changed.'],'First group by pupa: M yes; F/P/R no. Then milk feeding: P yes; F/M/R no. All four share egg-laying. Accept desk sorting, pointing or writing.',table=table(['Feature','Question to use'],[['Egg location','Where are eggs laid?'],['Pupa','Is this stage in the route?'],['Milk feeding','Do young receive milk?']])),slide('We do',0,'Build a precise comparison',['W2. Compare common frog with monarch.','Give one similarity and one difference.','Use “both”, “whereas” or a labelled pair.'],'Both lay eggs and have larvae; monarch has pupa whereas frog does not. Do not accept merely different colours or sizes unsupported by cards.'),slide('We do',0,'The claim challenge',['W3. “All egg-layers are birds.”','Select a counterexample and explain it.','Can four species describe every animal?'],'Platypus, frog or monarch disproves claim; platypus specifically demonstrates an egg-laying mammal. Four examples do not describe all species. Reveal after pupil reasoning.',reveal='The platypus lays eggs and is a mammal. That one case breaks the “all birds” claim.'),slide('Hinge',3,'Which comparison uses evidence fairly?',['Choose the statement that the cards support.'],'A false identical cycles. B correct feature-based comparison. C false all mammals live birth.',options=opts([('Frog and monarch have identical life cycles because both lay eggs.',False,'Shared eggs do not erase differences such as the pupa stage.'),('Frog and monarch both have larvae, but only the monarch has a pupa.',True,'The same stages are compared using both cards.'),('A platypus cannot be a mammal because it lays eggs.',False,'The platypus is an egg-laying mammal and its young receive milk.')]))]
    common_tail(d,['Choose one response route.','Build an evidence-based comparison.','Test one broad claim with a named case.'],['Use the same feature for both animals.','Name your species and evidence card.','Distinguish “these examples” from “all animals”.'],['Show a precise similarity or difference.','Check the named evidence.','Improve one broad or vague statement.'],['E1. Give a frog–monarch similarity.','E2. Give one difference in stages.','E3. Explain a counterexample to “all egg-layers are birds”.'],'Eggs/larvae shared; pupa only monarch; any named non-bird egg-layer with accurate reason. E4 on page asks about the next generation.')
    d['pupilPages']=[page('1 • Shared evidence: comparison bureau','Named-species summaries. Use these cards for W1–W3 and your selected route.',[cards(cardspec),response('W1. Group the four species by pupa stage, then by milk feeding. Why do groups change?',2),response('W2. Compare frog and monarch: one similarity and one difference.',2),response('W3. Give a counterexample to “all egg-layers are birds”.',2)]),page('2 • Supported route: compare a pair','Use cards F and M. Word bank: eggs / larva / pupa / adult.',[choices('S1. Which stage occurs in both routes?',['Egg','Pupa']),response('S2. Complete: Both have a ____ stage. The monarch has a ____ ; the common frog does not.',3),response('S3. Put these monarch stages in order: adult, egg, pupa, caterpillar.',3),choices('S4. A platypus lays eggs. Is it a bird?',['Yes','No: it is a mammal']),response('S5. Explain why “all egg-layers are birds” is wrong. Name one card.',4)]),page('3 • Standard route: feature table','Use the same question for each animal.',[tb(['Species','Pupa present?','Young receive milk?'],[['Common frog','',''],['Monarch','',''],['Platypus','',''],['Robin','','']]),response('N1. Complete the table using the species cards.',2),response('N2. Compare frog and monarch using one similarity and one difference.',3),response('N3. Compare platypus and robin using egg-laying and feeding of young.',3),response('N4. Correct “all egg-layers are birds”. Explain why four species do not describe every animal.',3)]),page('4 • Stretch route: challenge the rules','A strong claim stays within the evidence.',[response('T1. Write a comparison of two species using three matched features.',5),response('T2. Evaluate “all larvae become pupae” using the frog and monarch cards.',4),response('T3. Evaluate “all mammals give live birth”. Identify a counterexample and its classification evidence.',4),response('T4. A fifth species has no feeding information. Can you record “no parental feeding”? Explain a better entry.',3)]),page('5 • Exit and reflection','Answer independently using scientific features.',[response('E1. Give one similarity between frog and monarch cycles.',3),response('E2. Give one difference in their stages.',3),response('E3. Give a counterexample to “all egg-layers are birds”. Explain.',3),response('E4. Does an adult turn into its own egg? Explain the cycle arrow.',3),response('Reflection. Which comparison question would you investigate next?',3)])]
    d['answers']=[ans('R1–R3','Reproduce; a named animal with a larva such as frog or monarch; no, the next generation contains new individuals.'),ans('W1–W3','W1 pupa: monarch yes, other three no; milk: platypus yes, other three no. Groups change because the feature changes. W2 both eggs/larvae; monarch has pupa and frog does not. W3 frog, monarch or platypus is a non-bird egg-layer; platypus is a mammal.'),ans('Hinge A–C','A false: same feature is not identical cycle. B correct. C false: platypus is an egg-laying mammal.'),ans('S1–S5','S1 egg. S2 larva; pupa. S3 egg→caterpillar→pupa→adult. S4 no, mammal. S5 name a non-bird egg-layer and state that this contradicts all egg-layers being birds.'),ans('N1–N4','N1 frog no/no; monarch yes/no; platypus no/yes; robin no/no. N2 both eggs or larvae, but pupa only monarch. N3 both lay eggs; platypus young receive milk whereas robin chicks receive other food from parents. N4 valid counterexample; a sample of four cannot establish every possible animal life cycle.'),ans('T1–T4','T1 three accurately matched features, for example frog and monarch: egg location pond versus milkweed, larvae both, pupa absent versus present. T2 false: tadpoles are larvae but no pupa follows. T3 false: platypus lays eggs and feeds young milk. T4 missing information is not evidence of absence; record not supplied/unknown and seek a reliable source.'),ans('E1–E4 / assessment','E1 eggs or larvae. E2 pupa only monarch. E3 named correct non-bird case and contradiction. E4 adults produce new offspring, not themselves becoming eggs. Secure: matched comparison and valid counterexample; re-teach vague differences by selecting one common feature question. Reflection accepts a relevant evidence question.')]
    interactive(d,'Comparison bureau: change the sorting rule',[( 'Common frog and monarch both have which stage?', [('A larva.',True,'Tadpole and caterpillar are different larval forms.'),('A pupa.',False,'The common frog route has no pupa.')],'Use the same stage question for both routes.'),('Which sorting rule places only the monarch in the yes group?',[('Has a pupa.',True,'The monarch has a pupa; the other three named examples do not.'),('Lays eggs.',False,'All four named examples lay eggs.')],'Regrouping tests a different feature, as in W1.'),('Does egg-laying prove an animal is a bird?',[('No: the platypus is an egg-laying mammal.',True,'A named counterexample disproves the all-birds rule.'),('Yes: one feature is enough.',False,'Egg-laying occurs in several animal groups.')],'Explain a precise counterexample for W3.')])
    finish(d,['The comparison extends the earlier life-cycle archive using a new counterexample and a matched-feature matrix. It intentionally revisits species knowledge rather than claiming untouched content.','Interactive sorting decisions map to W1–W3; paper cards support the same predict, check and explain cycle.'])

def checkpoint():
    dragon=source('Arizona State University: Incomplete metamorphosis','https://askabiologist.asu.edu/incomplete-metamorphosis','Checked September 2026. Egg–nymph–adult is different from complete metamorphosis; dragonfly nymphs are aquatic. The checkpoint supplies the necessary species clues.')
    d=base('grow_spring_evidence_exchange','The spring science evidence exchange','A short checkpoint in explaining, comparing and improving','Use evidence to explain life cycles and apply selected spring science ideas in a teacher-authored checkpoint.',2,['Recall life-cycle stages, heart pumping and material testing.','Use values with units to support a claim.'],['Describe a life-cycle sequence and a meaningful comparison.','Explain a body-system job accurately.','Use material-test data and state a limit.'],[('evidence','Information used to support or challenge a claim.'),('explanation','An account of how or why something happens.'),('comparison','A similarity or difference using the same feature.'),('criterion','A feature used to judge whether work meets the goal.')],['Training sheet, one checkpoint route, pencils; optional calculator.'],['Give only shared training page 1 during I do and We do. Keep route pages 2–4 face down until You do.','Do not rehearse the checkpoint’s animal names, numerical values or answers before independent work.','Read or scribe neutrally; record any adult prompts separately.'],['No animal handling, exercise measurements, heat or electrical practical is needed.','Use private feedback and flexible support; do not infer qualification completion from this lesson.'],'All checkpoint evidence is supplied on the selected paper route. No internet or practical materials are needed.',[('A correct choice alone always proves understanding.','An explanation or evidence link shows more than a guess.','Ask which feature or number supports the choice.'),('A classroom checkpoint gives an official qualification result.','It samples taught ideas for feedback; qualification requirements need separate verification.','Ask what the checkpoint was designed to show.'),('One material result proves what always happens.','A conclusion should name the tested conditions and relevant limits.','Ask which extra test would strengthen the claim.')],['Short choices and sentence frames; same three science areas.','Explain three evidence cases with a comparison and numerical support.','Evaluate overclaims and suggest a precise next check.'],[MONARCH,dragon,source('NHLBI: The heart','https://www.nhlbi.nih.gov/health/heart','Heart pumping and blood transport reference, checked September 2026.'),RSC])
    v1=boxes('A worked example uses evidence',['Read the question','Find a matching\nobservation','Explain what\nit supports'],'Training example only. Checkpoint cases come later.')
    v2=vis('Training toy-car comparison','Two equal-height ramps lead onto surfaces A and B. The same toy car, release point and measuring rule are used. This training example is separate from the independent checkpoint.',[txt(40,25,920,55,'Training: compare one condition',32,bold=True),line(90,170,330,360,DARK,False),line(580,170,820,360,DARK,False),line(70,360,470,360,GREEN,False),line(550,360,950,360,BLUE,False),rect(120,160,75,40),rect(610,160,75,40),txt(75,405,395,80,'Surface A\nsame car and release',28),txt(555,405,395,80,'Surface B\nsame car and release',28),txt(75,105,850,45,'Same ramp height; change only the surface.',27)])
    v3=boxes('Separate observation from overclaim',['Observed:\nA travelled farther','Supported:\nin these trials','Not established:\nalways, everywhere'],'Training sample data: A 60, 58 cm; B 40, 42 cm.\nA claim must stay within the evidence.')
    trainrows=[['A','60','58'],['B','40','42']]
    d['slides']=[slide('Opening',2,'Show the science you can explain',['Today is a short teacher-authored checkpoint.','First practise how to use evidence.','The independent cases stay unseen until later.'],'Explain that this is feedback on selected taught content, not an official exam or grade predictor. Keep selected route pages face down.'),slide('Retrieval',3,'Remember the evidence habits',['R1. Why include units with a number?','R2. What does “in this test” tell a reader?','R3. Can an adult read a question without giving the answer?'],'Units give meaning; bounded context limits a claim; yes, neutral reading supports access. Do not review the checkpoint’s exact factual answers.'),slide('I do',8,'I model how to answer, not the checkpoint',['I read the question before choosing evidence.','I select a matching observation.','I explain the link in one clear sentence.'],'Think aloud using the training car example only. The purpose is a response routine; the independent lifecycle, body and materials cases are not shown or solved here.',visual=v1),slide('I do',0,'I inspect the comparison conditions',['The training car and ramp height stay the same.','The surface changes.','A fair comparison reduces other explanations.'],'Shared I do time. Trace the two ramps. This is a schematic, not a scale drawing. Model the control question: What else could change the result? Do not introduce checkpoint values.',visual=v2),slide('I do',0,'I bound the training claim',['The A values exceed the B values here.','I use a pair of values with centimetres.','I do not promise the same result everywhere.'],'Shared I do time. Model: In these constructed trials, A travelled farther, for example 60 cm versus 40 cm. Repeat conditions matter. Avoid using the independent insulation data.',visual=v3),slide('We do',8,'Training editor: improve the response',['W1. Which surface travelled farther in both trials?','W2. Give one pair of numbers and units.','W3. Repair “A always wins everywhere”.'],'Use the toy-car dataset only. A exceeds B in both trials; 60/40 or 58/42 cm. Replace always with in these sample trials and suggest more repeats or conditions.',table=table(['Training surface','Trial 1 / cm','Trial 2 / cm'],trainrows,'Constructed training data; different from the checkpoint.')),slide('We do',0,'Choose useful feedback',['Response: “A is best because I like it.”','Which feedback helps: add a number, or write faster?','Explain your choice.'],'Shared We do time. Add a numerical comparison that answers the question; speed is not the science goal. Allow private written choice.'),slide('We do',0,'Prepare for independent work',['Keep the response routine.','Put the training sheet aside.','Wait for your selected checkpoint page.'],'Shared We do time. Hand out or reveal pages 2, 3 or 4 only after the hinge. No answer key or teacher page should be visible.'),slide('Hinge',3,'Which is a useful evidence sentence?',['Use the training example only.'],'A unsupported preference. B accurate values/context. C universal overclaim. This tests evidence language, not checkpoint science answers.',options=opts([('A is better because it looks nicer.',False,'Appearance is not evidence about the measured distance.'),('In these trials, A travelled 60 cm and B 40 cm in trial 1.',True,'It gives relevant values, units and a clear boundary.'),('A must always travel farther in every situation.',False,'Two training trials do not establish every situation.')]))]
    common_tail(d,['Open your selected checkpoint route now.','Work independently on all three science cases.','Ask for reading support if needed.'],['Use the evidence printed on your route.','Show a reason as well as a choice.','Put a question mark beside anything uncertain.'],['Submit before seeing the worked answers.','Compare one response with the criteria.','Choose one precise improvement.'],['E1. Which science area is most secure for you?','E2. Write one corrected explanation after feedback.','E3. Name the evidence that supports it.'],'Exit is reflection after submission, not a second independent score. Accept a corrected lifecycle, body or material explanation with relevant evidence.')
    d['slides'][12]['notes']='Collect the independent checkpoint before discussing its answers. Use the separate teacher answers to give private criterion-based feedback. If pupils annotate afterwards, keep the original response visible so the first attempt is distinguishable.'
    d['pupilPages']=[page('1 • Training only: evidence habits','Use during I do and We do. Keep the checkpoint route face down until You do. The numbers below are constructed toy-car data.',[tb(['Surface','Trial 1 / cm','Trial 2 / cm'],trainrows),cards([('Same method','Same toy car, ramp height, release point and distance rule. Only the surface changes.'),('Claim to improve','“A always travels farther in every situation.” Two trials cannot establish every possible condition.'),('Evidence frame','In these trials, ____ . For example, ____ cm compared with ____ cm.'),('Access','Questions may be read aloud. A scribe records your own explanation, not an adult’s answer.')]),response('W1. Which surface travelled farther in both trials?',2),response('W2. Give one pair of values and units.',2),response('W3. Improve the claim and suggest one useful next check.',3)]),page('2 • Supported checkpoint: three science cases','Open only at You do. Work independently. Teacher may read the words.',[textblock('Case A: a ladybird has egg → larva → pupa → adult stages. A common frog has egg → tadpole → froglet → adult stages.'),choices('S1. Which animal has a pupa stage?',['Ladybird','Common frog']),response('S2. Give one life-cycle similarity and one difference.',3),choices('S3. Which job belongs to the heart?',['Pumps blood','Digests whole food']),textblock('Case B: constructed cooling data. Same bottles, starting at 30 °C, in a 20 °C room. After 10 minutes: no sleeve 24 °C; thick sleeve 28 °C.'),choices('S4. Which bottle cooled less in this test?',['No sleeve','Thick sleeve']),response('S5. Explain your choice using one temperature. Does the sleeve stop all energy transfer forever?',3)]),page('3 • Standard checkpoint: explain the evidence','Open only at You do. These are new cases and constructed data.',[textblock('Life-cycle cards: ladybird—egg, larva, pupa, adult; dragonfly—egg, aquatic nymph, adult. Both adults can produce a new generation.'),response('N1. Give one similarity and one difference between these cycles. Explain the arrow from adult to new eggs.',4),response('N2. Explain how digestion and blood transport work together. State the heart’s job.',4),tb(['Bottle sleeve','Start / °C','After 10 min / °C'],[['None','30','24'],['Thick fabric','30','28']]),textblock('Constructed sample data: same bottles and fill, same 20 °C room, one trial per sleeve.'),response('N3. Which bottle cooled less? Calculate both falls and explain the effect of insulation.',3),response('N4. Give one limit and one useful improvement to this test.',3)]),page('4 • Stretch checkpoint: test the claims','Open only at You do. Support each explanation; do not claim more than the cases show.',[textblock('Life-cycle evidence: ladybird has egg → larva → pupa → adult. Dragonfly has egg → aquatic nymph → adult. Platypus is an egg-laying mammal whose young receive milk.'),response('T1. Evaluate “every young insect becomes a pupa” and “all egg-layers are birds”. Use a named counterexample for each.',4),response('T2. Repair “The heart digests food and sends whole crumbs to tissues”. Link two systems accurately.',4),tb(['Sleeve','Start / °C','10 min / °C','Thickness'],[['None','30','24','0 mm'],['Fabric','30','28','8 mm']]),textblock('Constructed data: same bottles and fill; 20 °C room; one trial each.'),response('T3. Compare temperature falls. Explain why this does not prove fabric stops all energy transfer.',3),response('T4. Design one additional comparison to test thickness. Name a control and the measurement.',3)]),page('5 • Feedback and next step','Complete after submitting the independent checkpoint. This page records improvement, not a new independent score.',[response('E1. Which area is most secure: life cycles, body systems or materials? Name evidence from your answer.',3),response('E2. Write one corrected scientific explanation after feedback.',4),response('E3. What observation, number or process supports the correction?',3),response('E4. Choose one precise next practice task.',3),response('Reflection. Which kind of support helped you show your own science?',3)])]
    d['answers']=[ans('R1–R3 / training','Units give a number meaning; in this test bounds a claim; neutral reading can support access without supplying a conclusion. W1 A. W2 60 vs 40 or 58 vs 42 cm. W3 in these sample trials, A travelled farther; repeat and test further conditions. Useful feedback asks for evidence, not writing speed.'),ans('Hinge A–C','A preference is not distance evidence. B correct. C overclaims two trials.'),ans('S1–S5','S1 ladybird. S2 both eggs/adults; ladybird has pupa, frog does not. S3 pumps blood. S4 thick sleeve. S5 28 °C remains closer to the 30 °C start than 24 °C; it slowed cooling, not stopped all energy transfer forever.'),ans('N1–N4','N1 both eggs and reproductive adults; ladybird has pupa whereas dragonfly has nymph and no pupa. Adult→eggs represents new offspring, not the same individual becoming an egg. N2 digestion produces small absorbable nutrients which blood transports; heart pumps blood. N3 falls 6 °C and 2 °C; fabric slowed energy transfer out to the cooler room. N4 one trial limits confidence; repeat matched conditions. Other relevant limitations and specific improvements accepted.'),ans('T1–T4','T1 dragonfly nymph becomes adult without pupa; platypus is an egg-laying mammal. T2 digestive organs break some food molecules down; small nutrients are absorbed and carried in blood; heart pumps. T3 6 °C versus 2 °C; sleeved bottle still cools, so transfer continues. T4 same fabric at two measured thicknesses, matching bottles, fill, starting temperature and room; record temperature after a fixed duration and repeat.'),ans('Criteria and diagnostic response','Record each area as secure, developing or revisit, without an official grade. Life cycles secure: a valid matched comparison and generational meaning; body systems secure: correct pumping and absorption/transport link; materials secure: correct paired values, slows transfer and bounded conclusion. A correct choice without explanation is developing evidence. Re-teach only the area indicated: stage cards, two-system substance route, or warmer-to-cooler arrow.'),ans('E1–E4 / reflection','Accept a reasoned self-assessment tied to the submitted work. Corrections must be scientifically accurate and labelled as after feedback. A useful next task names a concept, such as distinguishing nymph from pupa or drawing energy direction, rather than simply “do more science”.')]
    interactive(d,'Training editor: evidence before the checkpoint',[( 'What should you read first?', [('The question being asked.',True,'It tells you which evidence is relevant.'),('Only the biggest number.',False,'A large value may not answer the question.')],'This models a response routine without showing the independent cases.'),('Which variable changes in the training comparison?',[('The surface.',True,'The stated method keeps the car and release conditions the same.'),('Every condition at once.',False,'Several changes would make explanations harder to separate.')],'Use the training method, not the unseen checkpoint.'),('What claim fits the car data?',[('A travelled farther in these sample trials.',True,'Both A values exceed the matched B values.'),('A must always travel farther everywhere.',False,'The limited trials do not establish every situation.')],'Put training aside before opening the independent route.')])
    finish(d,['This is original formative assessment of selected Spring content, not an official awarding-body paper or proof of qualification completion.','The training car example develops the evidence-response routine. The checkpoint uses different organisms, body-system questions and cooling values; do not reveal or rehearse these beforehand.','Interactive training uses only page 1. Collect checkpoint work before answer feedback; preserve the first attempt when pupils correct afterwards.'])

if __name__=='__main__':comparison();checkpoint()
